import sympy
from sympy import cos, pi, minpoly, totient, degree

# Top-level setup
# No specific named bindings are required for integer witnesses in this domain.

def conditions(witness):
    try:
        n = int(witness)
        # Check if witness is an integer and >= 3
        h1 = bool(n >= 3 and n == witness)
    except Exception:
        h1 = False

    try:
        if not h1:
            neg_q = False
        else:
            n = int(witness)
            # The maximal real subfield of Q(zeta_n) is generated by zeta_n + zeta_n^-1 = 2*cos(2*pi/n).
            # We check if its degree over Q is exactly phi(n)/2.
            gen = 2 * cos(2 * pi / n)
            mp = minpoly(gen)
            deg = degree(mp)
            expected = totient(n) // 2
            
            q = bool(deg == expected)
            neg_q = not q
    except Exception:
        neg_q = False

    return [h1, neg_q]

CONDITION_LABELS = [
    "H_1: n >= 3 is an integer",
    "¬Q: The maximal real subfield of Q(zeta_n) is not Q(zeta_n + zeta_n^-1) or its degree is not phi(n)/2"
]

N_HYP = 1
NEG_Q_INDEX = 1